<script setup lang="ts">
import ShopOrdersMobile from './ShopOrdersMobile.vue';
import {ref,onMounted} from 'vue';
import {t,formatAmount,formatDate,uiErrorMessage} from '@kuaixie/i18n';
import {useShop,shopStatusKey} from '@kuaixie/ui/useShop';
import type {PaymentPlatform} from '@kuaixie/sdk';
import {api,uploadPrivateImage,viewPrivateDocument} from '../api/client';
import {uniEventValue} from '../utils/uniEvent';
let platform:PaymentPlatform='h5';
// #ifdef MP-WEIXIN
platform='mp_weixin';
// #endif
// #ifdef APP-PLUS
platform='app';
// #endif
const p=useShop(api,async(title,content)=>!!(await uni.showModal({title,content})).confirm,platform),product=ref('');
async function upload(){await p.run(async()=>{const result=await uploadPrivateImage('store_license');p.application.licenseUploadId=result.id})}
async function view(id:string){try{const row=p.uploads.value.find(f=>f.id===id);await viewPrivateDocument(id,String(row?.content_type||'application/pdf'))}catch(e){p.error.value=uiErrorMessage(e)}}
onMounted(()=>{void p.load();void p.loadProducts()});
</script>
<template><view class="shop-mobile"><view class="op-title">{{t('shop.title')}}</view><view class="v15-notice">{{t('shop.boundary')}}</view><view v-if="p.error.value" class="op-error">{{p.error.value}}</view><view v-if="p.notice.value">{{p.notice.value}}</view><button :disabled="p.loading.value||p.busy.value" @click="p.load()">{{t('common.retry')}}</button><template v-if="p.state.value?.store"><ShopOrdersMobile/><view class="op-card"><view class="op-card-title">{{t(shopStatusKey(p.state.value.store.status))}}</view><text>{{t('shop.name')}}</text><input v-model="p.edit.name" maxlength="200" class="v15-field"/><text>{{t('shop.description')}}</text><textarea v-model="p.edit.description" maxlength="1000" class="v15-area"/><view class="op-muted">{{t('shop.feeReference')}} {{p.state.value.store.matching_fee_rate}}%</view><button :disabled="p.busy.value" @click="p.save()">{{t('account.save')}}</button><button v-if="p.state.value.store.status!=='suspended'" :disabled="p.busy.value" @click="p.status(p.state.value.store.id,p.state.value.store.status,p.state.value.store.status==='active'?'paused':'active')">{{t(p.state.value.store.status==='active'?'shop.pause':'shop.open')}}</button><button @click="p.preview(p.state.value.store.id)">{{t('shop.preview')}}</button><picker :range="p.products.value.map(row=>String(row.name))" @change="product=String(p.products.value[Number(uniEventValue($event))]?.id||'')"><view class="v15-selector">{{product||t('shop.products')}} ⌄</view></picker><button :disabled="!product||p.busy.value" @click="p.link(product)">{{t('shop.link')}}</button><button v-if="p.moreProducts.value" @click="p.loadProducts(true)">{{t('account.more')}}</button><button v-if="p.moreLinked.value" @click="p.linked()">{{t('account.more')}}</button><view v-for="row in p.state.value.products" :key="row.id" class="op-card"><text>{{row.name}} · {{formatAmount(row.price,'CNY')}}</text><button :disabled="p.busy.value" @click="p.link(row.id,true)">{{t('shop.unlink')}}</button></view></view></template><view v-else class="op-card"><view class="op-card-title">{{t('shop.apply')}}</view><text>{{t('shop.businessName')}}</text><input v-model="p.application.businessName" :disabled="p.busy.value||!!p.pending.value" maxlength="200" class="v15-field"/><text>{{t('shop.creditCode')}}</text><input v-model="p.application.creditCode" :disabled="p.busy.value||!!p.pending.value" maxlength="18" class="v15-field"/><text>{{t('shop.representative')}}</text><input v-model="p.application.representative" :disabled="p.busy.value||!!p.pending.value" maxlength="100" class="v15-field"/><text>{{t('shop.invitation')}}</text><input v-model="p.application.invitationCode" :disabled="p.busy.value||!!p.pending.value" maxlength="16" class="v15-field"/><button :disabled="p.busy.value||!!p.pending.value" @click="upload">{{t('shop.uploadLicense')}}</button><view>{{p.application.licenseUploadId||t('shop.selectLicense')}}</view><view v-for="file in p.uploads.value.filter(f=>!f.consumed_at)" :key="String(file.id)"><button :disabled="!!p.pending.value" @click="p.application.licenseUploadId=String(file.id)">{{file.original_name||file.id}}</button></view><view class="op-muted">{{t('upload.privateNotice')}}</view><button :disabled="p.busy.value" @click="p.apply()">{{t(p.pending.value?'case.retryPending':'shop.apply')}}</button></view><view v-for="row in p.state.value?.applications||[]" :key="row.id" class="op-card"><view>{{row.business_name}} · {{t(shopStatusKey(row.status))}}</view><view>{{row.review_note||''}} · {{formatDate(row.created_at)}}</view><button @click="view(row.license_upload_id)">{{t('shop.license')}}</button></view><view v-if="p.publicShop.value" class="op-card"><view class="op-card-title">{{p.publicShop.value.name}}</view><view>{{p.publicShop.value.description}}</view><button v-if="p.morePublic.value" @click="p.preview(p.publicShop.value.id,true)">{{t('account.more')}}</button><view v-for="row in p.publicShop.value.products" :key="row.id" @click="uni.navigateTo({url:'/pages/product-detail/index?id='+encodeURIComponent(row.id)})">{{row.name}} · {{formatAmount(row.price,'CNY')}}</view></view></view></template>
<style scoped>.shop-mobile{padding:16px}.shop-mobile text{display:block;margin:12px 0}.shop-mobile textarea{width:100%;box-sizing:border-box}.shop-mobile button{margin:10px 0}</style>
